use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn generate_probes_from_sparql (kb_file : & str , top_n : usize , output : & str , complexity_threshold : f64) -> Result < () > { println ! ("🔍 Generating AST probes from SPARQL queries...") ; let mut generator = SparqlProbeGenerator :: new () ; generator . load_rdf_data (kb_file) ? ; let mut all_probes = generator . generate_complexity_wrapper_probes (top_n) ; let high_complexity_query = split_decls_rs :: sparql_probe_bridge :: SparqlQuery { name : "high_complexity_monitor" . to_string () , query_type : split_decls_rs :: sparql_probe_bridge :: QueryType :: ComplexityAbove (complexity_threshold) , threshold : Some (complexity_threshold) , limit : Some (20) , target_template : "complexity_wrapper" . to_string () , } ; let template = split_decls_rs :: sparql_probe_bridge :: ProbeTemplate { node_type : split_decls_rs :: ast_reflector :: AstNodeType :: Function , action_template : "monitor_complex" . to_string () , wrapper_function : Some ("complexity_ping" . to_string ()) , priority : 2 , } ; let high_complexity_probes = generator . generate_probes_from_query (& high_complexity_query , & template) ; all_probes . extend (high_complexity_probes) ; let json = serde_json :: to_string_pretty (& all_probes) ? ; std :: fs :: write (output , json) ? ; println ! ("✅ Generated {} probes from SPARQL queries" , all_probes . len ()) ; println ! ("📊 Probe breakdown:") ; println ! ("   • Top {} complex functions: {}" , top_n , top_n . min (all_probes . len ())) ; println ! ("   • Functions above complexity {}: {}" , complexity_threshold , all_probes . len () - top_n . min (all_probes . len ())) ; println ! ("💾 Saved to: {}" , output) ; println ! ("\n🔍 Sample generated probes:") ; for (i , probe) in all_probes . iter () . take (3) . enumerate () { println ! ("   {}. {} -> {:?}" , i + 1 , probe . name , probe . action) ; } Ok (()) }
}